// Bundled sample photos, embedded as base64 data URLs (2026-11-04).
//
// Why embedded: the GitHub connector push carries UTF-8 text only, so the
// sample JPGs can never land in the repo as binary files — the live build
// fetched them as separate files and got 404s. Embedding the exact bytes in
// the bundle makes the "Try a sample photo" picker self-contained. The
// source files still live in frontend/public/samples/ for reference, but
// nothing at runtime fetches them.
//
// One sample per class, drawn from the project's own held-out test split
// (data/test) and verified through the real predict path before bundling —
// see EXTRA-FEATURES.md for the measured prediction of each file. The
// embedded bytes are byte-identical to those files (md5-checked when this
// module was generated, and pinned by tests/sample-images.test.ts).

export interface SampleImage {
  id: string;
  fabric: string;
  label: string;
  fileName: string;
  dataUrl: string;
}

export const SAMPLE_IMAGES: SampleImage[] = [
  {
    id: "cotton",
    fabric: "cotton",
    label: "Cotton",
    fileName: "sample-cotton.jpg",
    dataUrl: "data:image/jpeg;base64,",
  },
  {
    id: "denim",
    fabric: "denim",
    label: "Denim",
    fileName: "sample-denim.jpg",
    dataUrl: "data:image/jpeg;base64,",
  },
  {
    id: "silk",
    fabric: "silk",
    label: "Silk",
    fileName: "sample-silk.jpg",
    dataUrl: "data:image/jpeg;base64,",
  },
  {
    id: "wool",
    fabric: "wool",
    label: "Wool",
    fileName: "sample-wool.jpg",
    dataUrl: "data:image/jpeg;base64,",
  },
];

// Decode an embedded sample back into a File so it can travel the exact
// same onFileChange → analyze() path as an uploaded photo.
export function sampleImageFile(sample: SampleImage): File {
  const base64 = sample.dataUrl.slice(sample.dataUrl.indexOf(",") + 1);
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new File([bytes], sample.fileName, { type: "image/jpeg" });
}
